#[no_mangle]
pub unsafe extern "C" fn permutation_cipher(v:*const i64,n:usize)->i64{if v.is_null()||n<2||n>74{return -1}let a=std::slice::from_raw_parts(v,n);if !(0..=64).contains(&a[0]){return -1}let len=a[0]as usize;if n<len+2{return -1}let kp=len+1;if !(1..=8).contains(&a[kp]){return -1}let k=a[kp]as usize;if n!=kp+k+1{return -1}let mut seen=[false;8];for &x in &a[kp+1..]{if x<1||x>k as i64||seen[x as usize-1]{return -1}seen[x as usize-1]=true}let mut t=[0u8;128];let mut m=0usize;for &x in &a[1..=len]{if !(0..=127).contains(&x){return -1}let mut c=x as u8;if matches!(c,32|9|10|11|12|13){continue}if (b'a'..=b'z').contains(&c){c-=32}t[m]=c;m+=1}while m%k!=0{t[m]=b'X';m+=1}let mut h=0u64;for b in (0..m).step_by(k){for &pos in &a[kp+1..]{h=(h*257+t[b+pos as usize-1] as u64)%1_000_000_007}}h as i64}
